#!/usr/bin/env bash
# Utilisateurs : trier la majorité des comptes existants.
# - backend : user.markAdults — passe en majeurs les comptes choisis ENCORE « non renseignée » (jamais un mineur) ;
# - liste des utilisateurs : encadré « N compte(s) sans majorité renseignée », liste cochée, « Marquer majeurs » ;
# - guide admin « Gérer un membre », test e2e (compte de test dédié). Pas de migration.
# Prérequis : apply-droit-image-acces.sh.
# Usage (racine du repo) : bash apply-majorite-tri.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/users/router.ts" 2>/dev/null | grep -qF "markAdults"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "ImageConsentSummary" "apps/web/src/app/(public)/profil/page.tsx" 2>/dev/null || { echo "lancez d'abord apply-droit-image-acces.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/gerer-un-membre.mdx" "apps/web/src/features/admin/users/components/UsersTable.tsx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "e2e/data.mjs" "packages/backend/src/modules/users/router.ts")
CREATED=("apps/web/src/features/admin/users/legal/LegalAgeSortPanel.tsx" "e2e/majorite-tri.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "markAdults" "packages/backend/src/modules/users/router.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/admin/users/legal"
